  // Core dashboard / navigation copy. Keep whole sentences translated so Arabic
  // never falls back to word-by-word mixed text.
  'Describe a real need. Voxidence listens across communities, finds repeated evidence, compares multiple AI candidates, and returns one validated software direction.': 'صف حاجة حقيقية. يستمع فوكسيدنس إلى المجتمعات، ويكتشف الأدلة المتكررة، ويقارن بين عدة مقترحات بالذكاء الاصطناعي، ثم يعيد اتجاهًا برمجيًا واحدًا تم التحقق منه.',
  'Open my ideas': 'فتح أفكاري',
  'Each premium generation includes all advanced outputs immediately, plus contextual AI Chat for unlocked ideas.': 'يتضمن كل توليد بريميوم جميع المخرجات المتقدمة مباشرة، بالإضافة إلى محادثة ذكاء اصطناعي سياقية للأفكار المفتوحة.',
  'Review the result first. Direct payment appears only when you choose to unlock that specific idea.': 'راجع النتيجة أولًا. يظهر الدفع المباشر فقط عندما تختار فتح تلك الفكرة تحديدًا.',
