  'Using Nexora responsibly': 'استخدام فوكسيدنس بمسؤولية',
  'Voxidence helps users discover, generate, evaluate, and manage software project ideas. You must provide accurate account information and use the platform only for lawful, academic, research, or business purposes.': 'يساعد فوكسيدنس المستخدمين على اكتشاف أفكار المشاريع البرمجية وتوليدها وتقييمها وإدارتها. يجب تقديم معلومات حساب دقيقة واستخدام المنصة فقط لأغراض قانونية أو أكاديمية أو بحثية أو تجارية.',
  'Your account and generated content': 'حسابك والمحتوى المولّد',
  'You are responsible for protecting your login credentials and for reviewing AI-generated output before relying on it. Generated ideas may contain incomplete or inaccurate information and do not replace legal, financial, technical, or professional advice.': 'أنت مسؤول عن حماية بيانات تسجيل الدخول ومراجعة المخرجات المولدة بالذكاء الاصطناعي قبل الاعتماد عليها. قد تحتوي الأفكار المولدة على معلومات ناقصة أو غير دقيقة ولا تستبدل الاستشارات القانونية أو المالية أو التقنية أو المهنية.',
  'Acceptable use': 'الاستخدام المقبول',
  'You may not misuse the service, attempt unauthorized access, disrupt platform operation, scrape protected data, violate intellectual-property rights, or use Nexora to create harmful or illegal content.': 'لا يجوز إساءة استخدام الخدمة أو محاولة الوصول غير المصرح به أو تعطيل تشغيل المنصة أو استخراج البيانات المحمية أو انتهاك حقوق الملكية الفكرية أو استخدام فوكسيدنس لإنشاء محتوى ضار أو غير قانوني.',
  'Availability and changes': 'التوفر والتغييرات',
  'Features, limits, pricing, and supported AI providers may change as the graduation project evolves. We may suspend access when necessary to protect users, data, or platform security.': 'قد تتغير الميزات والحدود والأسعار ومزودو الذكاء الاصطناعي المدعومون مع تطور مشروع التخرج. وقد يتم تعليق الوصول عند الحاجة لحماية المستخدمين أو البيانات أو أمان المنصة.',
  'Information we process': 'المعلومات التي نعالجها',
  'Nexora may process your name, email address, account type, authentication data, generated ideas, publication activity, feedback, voting, ratings, payment records, and technical usage information needed to operate the platform.': 'قد يعالج فوكسيدنس اسمك وبريدك الإلكتروني ونوع الحساب وبيانات المصادقة والأفكار المولدة ونشاط النشر والملاحظات والتصويتات والتقييمات وسجلات الدفع ومعلومات الاستخدام التقنية اللازمة لتشغيل المنصة.',
  'Why we use it': 'لماذا نستخدمها',
  'We use this information to create and secure your account, deliver idea-generation features, save your workspace, support publications and interactions, process payments, improve reliability, and prevent abuse.': 'نستخدم هذه المعلومات لإنشاء حسابك وتأمينه وتقديم ميزات توليد الأفكار وحفظ مساحة عملك ودعم المنشورات والتفاعلات ومعالجة المدفوعات وتحسين الموثوقية ومنع إساءة الاستخدام.',
  'AI and service providers': 'مزودو الذكاء الاصطناعي والخدمات',
  'Content submitted for generation may be sent to configured AI or infrastructure providers solely to perform the requested service. Payment details are handled by the selected payment provider and are not stored as raw card data by Nexora.': 'قد يُرسل المحتوى المقدم للتوليد إلى مزودي الذكاء الاصطناعي أو البنية التحتية المضبوطين فقط لتنفيذ الخدمة المطلوبة. يتعامل مزود الدفع المحدد مع تفاصيل الدفع ولا يخزن فوكسيدنس بيانات البطاقة الخام.',
  'Your choices': 'خياراتك',
  'You may review or update your profile information and request account deletion through supported settings. Some records may be retained when required for security, audit, payment, or legal obligations.': 'يمكنك مراجعة معلومات ملفك الشخصي أو تحديثها وطلب حذف الحساب عبر الإعدادات المدعومة. قد يتم الاحتفاظ ببعض السجلات عند الحاجة لأغراض الأمان أو التدقيق أو الدفع أو الالتزامات القانونية.',
