  'Your message was sent successfully. Our team will review it soon.': 'تم إرسال رسالتك بنجاح. سيراجعها فريقنا قريبًا.',
  'Public conversations, reviews, developer communities, and recurring needs flow into one evidence source.': 'تتجمع المحادثات العامة والمراجعات ومجتمعات المطورين والاحتياجات المتكررة في مصدر أدلة واحد.',
  'The pipeline cleans the data, runs NLP analysis, detects patterns, and prepares grounded context.': 'ينظف المسار البيانات ويجري تحليل معالجة اللغة الطبيعية ويكتشف الأنماط ويجهز سياقًا قائمًا على الأدلة.',
  'Multiple candidate directions are scored against signal strength, community demand, and potential impact.': 'يتم تقييم عدة اتجاهات مرشحة وفق قوة الإشارة وطلب المجتمع والأثر المحتمل.',
  'The selected direction becomes a focused, evidence-backed project brief that is ready to build.': 'يتحول الاتجاه المختار إلى ملخص مشروع واضح ومدعوم بالأدلة وجاهز للبناء.',
