  'Hear what communities need.': 'استمع لما تحتاجه المجتمعات.',
  'Build what truly matters.': 'ابنِ ما يهم فعلًا.',
  'Voxidence listens across real public conversations, reveals the needs that keep resurfacing, and transforms verified evidence into focused software opportunities ready to explore.': 'يستمع فوكسيدنس إلى المحادثات العامة الحقيقية، ويكشف الاحتياجات المتكررة، ويحوّل الأدلة الموثقة إلى فرص برمجية مركزة جاهزة للاستكشاف.',
