  'Repeated conversations expose real frustrations, gaps, and unmet needs.': 'تكشف المحادثات المتكررة عن معاناة وفجوات واحتياجات حقيقية غير ملباة.',
  'Evidence extraction': 'استخراج الأدلة',
  'NLP organizes patterns, urgency, context, and supporting evidence.': 'تنظم معالجة اللغة الطبيعية الأنماط والإلحاح والسياق والأدلة الداعمة.',
  'Multiple candidates are generated, scored, and compared for strength.': 'يتم توليد عدة مرشحين وتقييمهم ومقارنتهم حسب القوة.',
