  'Access is granted only after the provider webhook is verified.': 'يُمنح الوصول فقط بعد التحقق من إشعار مزود الدفع.',
  'Your payment is verified. Voxidence is generating and attaching the advanced idea outputs now.': 'تم التحقق من دفعتك. يقوم فوكسيدنس الآن بتوليد مخرجات الفكرة المتقدمة وإرفاقها.',
  'Your payment is verified. Voxidence is attaching the advanced publication outputs now.': 'تم التحقق من دفعتك. يقوم فوكسيدنس الآن بإرفاق مخرجات النشر المتقدمة.',
  'Voxidence is verifying the provider session and applying your access safely.': 'يتحقق فوكسيدنس من جلسة مزود الدفع ويطبق وصولك بأمان.',
  'The payment reference was not returned by the provider. Return to the idea and try again; you will not be charged twice for an already completed unlock.': 'لم يُرجع مزود الدفع مرجع العملية. عد إلى الفكرة وحاول مرة أخرى، ولن يتم خصم المبلغ مرتين لعملية فتح مكتملة.',
