  "Use Voxidence Chat while your account is Premium to explore and refine ideas that are already unlocked.": "استخدم محادثة فوكسيدنس أثناء تفعيل بريميوم لاستكشاف الأفكار المفتوحة وتطويرها.",
  "Browse all active published ideas even when a publication was originally limited to another audience category.": "استعرض جميع الأفكار المنشورة النشطة حتى لو كانت موجهة أصلًا لفئة جمهور أخرى.",
  "Use the Premium acceptance flow for published ideas, then spend the configured credit cost only when unlocking advanced publication outputs.": "استخدم مسار القبول الخاص ببريميوم للأفكار المنشورة، ولا يُخصم الرصيد المحدد إلا عند فتح المخرجات المتقدمة للمنشور.",
  "Ideas and outputs already generated or unlocked remain available even after your credit balance reaches zero.": "تبقى الأفكار والمخرجات التي تم توليدها أو فتحها متاحة حتى بعد وصول رصيدك إلى الصفر.",
