const ARABIC_NORMALIZED_PHRASES = new Map(
  [
    ...Object.entries(ADMIN_ARABIC_PHRASES),
    ...Object.entries(ARABIC_PHRASES),
    ...Object.entries(ARABIC_SUPPLEMENTAL_PHRASES),
  ].map(([key, translation]) => [key.trim().toLocaleLowerCase('en-US'), translation]),
);

function preserveCaseLookup(value) {
  const exact =
    ARABIC_SUPPLEMENTAL_PHRASES[value] ||
    ARABIC_PHRASES[value] ||
    ADMIN_ARABIC_PHRASES[value];
  if (exact) return exact;

  const normalized = value.trim();
  return (
    ARABIC_SUPPLEMENTAL_PHRASES[normalized] ||
    ARABIC_PHRASES[normalized] ||
    ADMIN_ARABIC_PHRASES[normalized] ||
    ARABIC_NORMALIZED_PHRASES.get(normalized.toLocaleLowerCase('en-US')) ||
    null
  );
}

