function escapeRegExp(value) {
  return value.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

const SORTED_ARABIC_CONTENT_PHRASES = [...ARABIC_CONTENT_PHRASES]
  .sort((left, right) => right[0].length - left[0].length);

function applyContentPhraseTranslations(value) {
  let translated = value;
  for (const [english, arabic] of SORTED_ARABIC_CONTENT_PHRASES) {
    translated = translated.replace(new RegExp(escapeRegExp(english), 'gi'), arabic);
  }
  return translated;
}

const ARABIC_ADMIN_DATE_TOKENS = Object.freeze({
  January: 'يناير', Jan: 'يناير',
  February: 'فبراير', Feb: 'فبراير',
  March: 'مارس', Mar: 'مارس',
  April: 'أبريل', Apr: 'أبريل',
  May: 'مايو',
  June: 'يونيو', Jun: 'يونيو',
  July: 'يوليو', Jul: 'يوليو',
  August: 'أغسطس', Aug: 'أغسطس',
  September: 'سبتمبر', Sep: 'سبتمبر', Sept: 'سبتمبر',
  October: 'أكتوبر', Oct: 'أكتوبر',
  November: 'نوفمبر', Nov: 'نوفمبر',
  December: 'ديسمبر', Dec: 'ديسمبر',
  AM: 'ص', PM: 'م',
});

function translateAdminDateFragment(value) {
  return String(value || '').replace(
    /\b(January|Jan|February|Feb|March|Mar|April|Apr|May|June|Jun|July|Jul|August|Aug|September|Sept|Sep|October|Oct|November|Nov|December|Dec|AM|PM)\b/g,
    (token) => ARABIC_ADMIN_DATE_TOKENS[token] || token,
  );
}

function translateFallback(core) {
  if (/^(https?:\/\/|www\.|[\w.+-]+@[\w.-]+\.|#[0-9a-f]{3,8}$)/i.test(core)) return core;

  // Arabic mode must never fabricate Arabic by transliterating or translating
  // arbitrary words one-by-one. Exact UI phrases above are curated by hand.
  // For generated/server content we only accept a structured phrase rewrite
  // when it produces a complete Arabic result; otherwise the source text is
  // preserved intact instead of showing broken or literal Arabic.
  const phraseTranslated = applyContentPhraseTranslations(core);
  if (phraseTranslated !== core && !/[A-Za-z]/.test(phraseTranslated)) {
    return phraseTranslated;
  }

  return core;
}

export function translateToArabic(value) {
  if (typeof value !== 'string' || !/[A-Za-z]/.test(value)) return value;
  const trimmed = value.trim();
  if (trimmed === 'Voxidence') return value;
  if (/^(https?:\/\/|www\.|[\w.+-]+@[\w.-]+\.|#[0-9a-f]{3,8}$)/i.test(trimmed)) return value;

  const exact = preserveCaseLookup(value);
  if (exact) return exact;

  const prefix = value.match(/^\s*/)?.[0] ?? '';
  const suffix = value.match(/\s*$/)?.[0] ?? '';
  const core = trimmed;
  const direct = preserveCaseLookup(core);
  if (direct) return `${prefix}${direct}${suffix}`;

  const isolate = (text) => `\u2066${text}\u2069`;
  const dynamicPatterns = [
    [/^(January|Jan|February|Feb|March|Mar|April|Apr|May|June|Jun|July|Jul|August|Aug|September|Sept|Sep|October|Oct|November|Nov|December|Dec)\b.*$/i, (m) => translateAdminDateFragment(m[0])],
    [/^(\d[\d,]*)\s+matching\s+domains$/i, (m) => `${m[1]} مجال مطابق`],
    [/^(\d[\d,]*)\s+configured\s+keywords$/i, (m) => `${m[1]} كلمة مفتاحية مهيأة`],
    [/^(\d[\d,]*)\s+ideas$/i, (m) => `${m[1]} فكرة`],
    [/^(\d[\d,]*)\s+generated\s+ideas?$/i, (m) => `${m[1]} فكرة مولّدة`],
    [/^\+(\d+)\s+more$/i, (m) => `+${m[1]} إضافية`],
    [/^(\d[\d,]*)\s+matching\s+(?:record|records)$/i, (m) => `${m[1]} سجل مطابق`],
    [/^(\d[\d,]*)\s+matching\s+(?:record|records)\s+across\s+the\s+current\s+filters\.$/i, (m) => `${m[1]} سجل مطابق ضمن عوامل التصفية الحالية.`],
    [/^(\d[\d,]*)\s+admin$/i, (m) => `${m[1]} إجراء مشرف`],
    [/^(\d[\d,]*)\s+system$/i, (m) => `${m[1]} حدث نظام`],
    [/^(\d[\d,]*)\s+actors$/i, (m) => `${m[1]} منفذ`],
    [/^(\d[\d,]*)\s+(?:field|fields)\s+changed$/i, (m) => `تم تغيير ${m[1]} حقل`],
    [/^(\d[\d,]*)\s+changed\s+fields$/i, (m) => `${m[1]} حقل متغير`],
    [/^(\d[\d,]*)\s+unsaved\s+changes$/i, (m) => `${m[1]} تغييرات غير محفوظة`],
    [/^(\d[\d,]*)\s+(?:setting|settings)\s+will\s+change\.$/i, (m) => `سيتم تغيير ${m[1]} إعداد`],
    [/^Minimum\s+allowed\s+value\s+is\s+(.+)\.$/i, (m) => `الحد الأدنى المسموح به هو ${m[1]}.`],
    [/^(\d[\d,]*)\s+matching\s+(?:source|sources)$/i, (m) => `${m[1]} مصدر مطابق`],
    [/^(\d[\d,]*)\s+source\s+state\s+synchronized\.$/i, () => 'تمت مزامنة حالة مصدر واحد'],
    [/^(\d[\d,]*)\s+source\s+states\s+synchronized\.$/i, (m) => `تمت مزامنة حالات ${m[1]} مصادر`],
    [/^Manage\s+(.+)$/i, (m) => `إدارة ${isolate(m[1])}`],
    [/^(\d[\d,]*)\s+alerts already read$/i, (m) => `${m[1]} تنبيهًا تمت قراءته`],
    [/^(\d[\d,]*)\s+recipients$/i, (m) => `${m[1]} مستلمًا`],
    [/^(\d[\d,]*)\s+selected\s+(?:user|users)$/i, (m) => `${m[1]} مستخدمًا محددًا`],
    [/^(\d[\d,]*)\s+selected\s+(?:recipient|recipients)$/i, (m) => `${m[1]} مستلمًا محددًا`],
    [/^Showing\s+(\d+)–(\d+)\s+of\s+(\d+)$/i, (m) => `عرض ${m[1]}–${m[2]} من ${m[3]}`],
    [/^Page\s+(\d+)\s+of\s+(\d+)$/i, (m) => `الصفحة ${m[1]} من ${m[2]}`],
    [/^(\d+)\s+deliveries\s+·\s+(\d+)\s+email failures$/i, (m) => `${m[1]} عمليات تسليم · ${m[2]} حالات فشل للبريد الإلكتروني`],
    [/^Sent by\s+(.+)$/i, (m) => `أُرسل بواسطة ${isolate(m[1])}`],
    [/^(\d+)\s+additional domains available$/i, (m) => `${m[1]} مجالًا إضافيًا متاحًا`],
    [/^(.+?) Regional Identity Diagnostic and Guidance Portal$/i, (m) => `بوابة ${translateFallback(m[1])} لتشخيص الهوية الإقليمية والإرشاد`],
    [/^(.+?) Regional Login Compatibility and Guidance Assistant$/i, (m) => `مساعد ${translateFallback(m[1])} لتوافق تسجيل الدخول الإقليمي والإرشاد`],
    [/^Nablus Cross-Device Access Bridge$/i, () => 'جسر نابلس للوصول عبر الأجهزة'],
    [/^The proposed pilot is supported by one retained direct community report and should be treated as a preliminary, not market-wide, signal\.?$/i, () => 'يدعم النموذج التجريبي المقترح تقرير مجتمعي مباشر واحد تم الاحتفاظ به، لذلك يجب اعتباره إشارة أولية لا دليلًا على مستوى السوق.'],
    [/^Welcome back,\s*(.+?)\.?$/i, (m) => `مرحبًا بعودتك، ${translateFallback(m[1].replace(/\.$/, ''))}.`],
    [/^Welcome back\s+(.+?)$/i, (m) => `مرحبًا بعودتك، ${isolate(m[1])}`],
    [/^Delete\s+(.+)$/i, (m) => `حذف ${isolate(m[1])}`],
    [/^We sent a six-digit approval code to\s+(.+?)\.\s+Your email remains unchanged until both steps are complete\.$/i, (m) => `أرسلنا رمز موافقة مكوّنًا من ستة أرقام إلى ${isolate(m[1])}. سيبقى بريدك الإلكتروني دون تغيير حتى اكتمال الخطوتين.`],
    [/^Your current email is approved\.\s+Enter the new code sent to\s+(.+?)\s+to finish the change\.$/i, (m) => `تم تأكيد بريدك الإلكتروني الحالي. أدخل الرمز الجديد المرسل إلى ${isolate(m[1])} لإكمال التغيير.`],
    [/^(.+?)\s+profile$/i, (m) => `الملف الشخصي لـ ${isolate(m[1])}`],
    [/^(.+?)\s+on\s+(.+)$/i, (m) => `${translateToArabic(m[1])} على ${translateToArabic(m[2])}`],
    [/^Active\s+(\d+)\s+min\s+ago$/i, (m) => `نشط منذ ${m[1]} دقيقة`],
    [/^Active\s+(\d+)\s+hr\s+ago$/i, (m) => `نشط منذ ${m[1]} ساعة`],
    [/^Active\s+(.+)$/i, (m) => `نشط ${translateToArabic(m[1])}`],
    [/^(.+?)\s+was signed out successfully\.$/i, (m) => `تم تسجيل خروج ${translateToArabic(m[1])} بنجاح.`],
    [/^Remove\s+(\d+)\s+star rating$/i, (m) => `إزالة تقييم ${m[1]} نجوم`],
    [/^Rate\s+(\d+)\s+out of\s+5$/i, (m) => `تقييم ${m[1]} من 5`],
    [/^Open\s+(.+?)\s+available advanced outputs in one premium workspace\.$/i, (m) => `افتح ${translateToArabic(m[1])} من المخرجات المتقدمة المتاحة في مساحة بريميوم واحدة.`],
    [/^(\d+)\s+credits$/i, (m) => `${m[1]} رصيد`],
    [/^The\s+(.+?)\s+exchange rate could not be refreshed right now\.\s+Retry in a moment or change your saved currency in Preferences\.$/i, (m) => `تعذر تحديث سعر صرف ${isolate(m[1])} الآن. أعد المحاولة بعد قليل أو غيّر العملة المحفوظة في التفضيلات.`],
    [/^At least\s+(\d+)\s+credits are required for this purchase\.$/i, (m) => `يلزم ${m[1]} رصيد على الأقل لإتمام هذا الشراء.`],
    [/^Minimum\s+(\d+)\s+credits to activate Premium$/i, (m) => `الحد الأدنى ${m[1]} رصيد لتفعيل بريميوم`],
    [/^1 credit =\s+(.+)$/i, (m) => `رصيد واحد = ${isolate(m[1])}`],
    [/^(.+?)\s+applies when a Normal account activates Premium\.$/i, (m) => `تُطبق ${isolate(m[1])} عند تفعيل حساب عادي لبريميوم.`],
    [/^(\d+)\s+credits subtotal:\s+(.+)\.$/i, (m) => `المجموع الفرعي لـ ${m[1]} رصيد: ${isolate(m[2])}.`],
    [/^Generation\s+(\d+)%\s+complete$/i, (m) => `اكتمل ${m[1]}٪ من التوليد`],
    [/^(\d+)\s+more to personalize$/i, (m) => `متبقي ${m[1]} للتخصيص`],
    [/^(\d+)\s+interests selected$/i, (m) => `تم اختيار ${m[1]} اهتمامات`],
    [/^(\d+)\s+ratings$/i, (m) => `${m[1]} تقييم`],
    [/^(.+?)\s+is ready to generate\.$/i, (m) => `${isolate(m[1])} جاهز للتوليد.`],
    [/^(.+?)\s+business model preview$/i, (m) => `معاينة نموذج عمل ${isolate(m[1])}`],
    [/^Thank you!\s+Your\s+(\d+)-star rating was saved\.$/i, (m) => `شكرًا! تم حفظ تقييمك بقيمة ${m[1]} نجوم.`],
    [/^Sign out\s+(.+?)\?$/i, (m) => `تسجيل خروج ${translateToArabic(m[1])}؟`],
    [/^Expires\s+(.+)$/i, (m) => `تنتهي ${translateToArabic(m[1])}`],
    [/^(\d+)\s+credit$/i, (m) => `${m[1]} رصيد`],
    [/^(\d+)\s+premium credits?$/i, (m) => `${m[1]} من رصيد بريميوم`],
    [/^(\d+)\s+premium credits? remaining$/i, (m) => `متبقي ${m[1]} من رصيد بريميوم`],
    [/^(\d+)\s+credits? remaining$/i, (m) => `متبقي ${m[1]} رصيد`],
    [/^(\d+)\s+free discoveries ready$/i, (m) => `${m[1]} استكشافات مجانية متاحة`],
    [/^One free discovery remains$/i, () => 'تبقى محاولة استكشاف مجانية واحدة'],
    [/^Reply will be sent to\s+(.+)$/i, (m) => `سيتم إرسال الرد إلى ${isolate(m[1])}`],
    [/^(\d+)\s+of\s+(\d+)\s+domains selected$/i, (m) => `تم اختيار ${m[1]} من ${m[2]} مجالات`],
    [/^(\d+)\s+sections available$/i, (m) => `${m[1]} قسمًا متاحًا`],
    [/^(\d+)\s+advanced outputs?$/i, (m) => `${m[1]} مخرجًا متقدمًا`],
    [/^Page\s+(\d+)\s+of\s+(\d+)$/i, (m) => `الصفحة ${m[1]} من ${m[2]}`],
    [/^Step\s+(\d+)\s+of\s+(\d+)$/i, (m) => `الخطوة ${m[1]} من ${m[2]}`],
    [/^(\d+)\s+results?$/i, (m) => `${m[1]} نتيجة`],
    [/^(\d+)\s+unread$/i, (m) => `${m[1]} غير مقروء`],
    [/^(\d+)\s+total$/i, (m) => `${m[1]} إجمالي`],
    [/^(\d+)\s+sessions?$/i, (m) => `${m[1]} جلسة`],
    [/^(\d+)\s+people$/i, (m) => `${m[1]} شخص`],
    [/^(\d+)\s+records?$/i, (m) => `${m[1]} سجل`],
    [/^(\d+)\s+sources?$/i, (m) => `${m[1]} مصدر`],
    [/^(\d+)\s+runs?$/i, (m) => `${m[1]} عملية`],
    [/^(\d+)\s+fields?$/i, (m) => `${m[1]} حقل`],
    [/^(\d+)\s+transactions?$/i, (m) => `${m[1]} معاملة`],
    [/^(\d+)\s+characters?$/i, (m) => `${m[1]} حرف`],
    [/^(\d+)\s+selected$/i, (m) => `تم اختيار ${m[1]}`],
    [/^(\d+)\s+ready$/i, (m) => `${m[1]} جاهز`],
    [/^(\d+)\s+options?$/i, (m) => `${m[1]} خيار`],
    [/^(\d+)\s+available$/i, (m) => `${m[1]} متاح`],
    [/^(\d+)\s+words?$/i, (m) => `${m[1]} كلمة`],
    [/^(\d+)\/(\d+)\s+words$/i, (m) => `${m[1]}/${m[2]} كلمة`],
    [/^Too long — keep it within (\d+) words\.$/i, (m) => `النص طويل جدًا — اجعله ضمن ${m[1]} كلمة.`],
    [/^(\d+)\s+evidence score$/i, (m) => `تقييم الأدلة ${m[1]}`],
    [/^(\d+)\s+additional domains?$/i, (m) => `${m[1]} مجال إضافي`],
    [/^(\d+)\s+more domains?$/i, (m) => `${m[1]} مجال إضافي`],
    [/^Reference:\s*(.+)$/i, (m) => `المرجع: ${isolate(m[1])}`],
    [/^Showing (\d+)[–-](\d+) of (\d+)$/i, (m) => `عرض ${m[1]}–${m[2]} من ${m[3]}`],
    [/^Page (\d+)$/i, (m) => `الصفحة ${m[1]}`],
    [/^of (\d+)$/i, (m) => `من ${m[1]}`],
    [/^(\d+)\s+changed$/i, (m) => `${m[1]} تغييرات`],
    [/^(\d+)\s+total updates?$/i, (m) => `${m[1]} تحديث إجمالًا`],
    [/^Version (\d+) · presentation ready$/i, (m) => `الإصدار ${m[1]} · العرض جاهز`],
    [/^Published by (.+)$/i, (m) => `نشر بواسطة ${isolate(m[1])}`],
    [/^Submitted (.+)$/i, (m) => `أُرسل ${m[1]}`],
    [/^Reviewed (.+)$/i, (m) => `تمت المراجعة ${m[1]}`],
    [/^Collected (.+)$/i, (m) => `جُمعت ${m[1]}`],
    [/^(\d+)\s+users?$/i, (m) => `${m[1]} مستخدم`],
    [/^(\d+)\s+configured domains?$/i, (m) => `${m[1]} مجال مهيأ`],
    [/^(\d+)\s+failed · (\d+) stopped$/i, (m) => `${m[1]} فشل · ${m[2]} متوقف`],
    [/^Created\s+(.+)$/i, (m) => `أُنشئت ${translateAdminDateFragment(m[1])}`],
    [/^Last updated\s+(.+)$/i, (m) => `آخر تحديث ${translateAdminDateFragment(m[1])}`],
    [/^Updated\s+(.+)$/i, (m) => `حُدّث ${translateFallback(m[1])}`],
  ];

  for (const [pattern, replacer] of dynamicPatterns) {
    const match = core.match(pattern);
    if (match) return `${prefix}${replacer(match)}${suffix}`;
  }

  // Final UI safety net: Arabic mode must not leak English interface fragments.
  // Exact translations remain the preferred path; this fallback also handles
  // new server statuses/titles until a polished phrase is added above.
  return `${prefix}${translateFallback(core)}${suffix}`;
}


const naturalArabicTranslationCache = new Map();
let naturalArabicTranslatorPromise = null;
let naturalArabicTranslatorUnsupported = false;
let activeDomLanguage = 'en';
const pendingNaturalTextTranslations = new WeakMap();


function shouldRequestNaturalArabic() {
  return false;
}

async function getNaturalArabicTranslator() {
  if (naturalArabicTranslatorUnsupported) return null;
  if (naturalArabicTranslatorPromise) return naturalArabicTranslatorPromise;

  const TranslatorApi = typeof window !== 'undefined' ? window.Translator : undefined;
  if (!TranslatorApi || typeof TranslatorApi.create !== 'function') {
    naturalArabicTranslatorUnsupported = true;
    return null;
  }

  naturalArabicTranslatorPromise = (async () => {
    try {
      if (typeof TranslatorApi.availability === 'function') {
        const availability = await TranslatorApi.availability({
          sourceLanguage: 'en',
          targetLanguage: 'ar',
        });
        if (availability === 'unavailable') {
          naturalArabicTranslatorUnsupported = true;
          return null;
        }
        if (
          (availability === 'downloadable' || availability === 'downloading') &&
          navigator?.userActivation &&
          !navigator.userActivation.hasBeenActive
        ) {
          return null;
        }
      }

      return await TranslatorApi.create({
        sourceLanguage: 'en',
        targetLanguage: 'ar',
      });
    } catch {
      return null;
    }
  })();

  const translator = await naturalArabicTranslatorPromise;
  if (!translator && !naturalArabicTranslatorUnsupported) {
    naturalArabicTranslatorPromise = null;
  }
  return translator;
}


function splitNaturalTranslationChunks(value, maxLength = 700) {
  const source = String(value || '').trim();
  if (source.length <= maxLength) return [source];

  const sentences = source.split(/(?<=[.!?])\s+/).filter(Boolean);
  const chunks = [];
  let current = '';

  for (const sentence of sentences) {
    if (!current) {
      current = sentence;
      continue;
    }
    if (`${current} ${sentence}`.length <= maxLength) {
      current = `${current} ${sentence}`;
    } else {
      chunks.push(current);
      current = sentence;
    }
  }
  if (current) chunks.push(current);
  return chunks.length ? chunks : [source];
}

async function requestNaturalArabicTranslation(source) {
  const cleanSource = String(source || '').trim();
  if (!shouldRequestNaturalArabic(cleanSource)) return source;

  const curated = translateToArabic(cleanSource);
  if (curated !== cleanSource && /[\u0600-\u06FF]/.test(curated)) {
    return curated;
  }

  if (naturalArabicTranslationCache.has(cleanSource)) {
    return naturalArabicTranslationCache.get(cleanSource);
  }

  const request = (async () => {
    const translator = await getNaturalArabicTranslator();
    if (!translator || typeof translator.translate !== 'function') return cleanSource;

    try {
      const translatedChunks = [];
      for (const chunk of splitNaturalTranslationChunks(cleanSource)) {
        const translatedChunk = String(await translator.translate(chunk) || '').trim();
        translatedChunks.push(translatedChunk || chunk);
      }
      const translated = translatedChunks.join(' ').trim();
      if (!translated || translated === cleanSource || !/[\u0600-\u06FF]/.test(translated)) {
        return cleanSource;
      }
      return translated;
    } catch {
      return cleanSource;
    }
  })();

  naturalArabicTranslationCache.set(cleanSource, request);
  return request;
}

function scheduleNaturalArabicTextTranslation(node, source) {
  if (!node || activeDomLanguage !== 'ar' || !shouldRequestNaturalArabic(source)) return;
  if (pendingNaturalTextTranslations.get(node) === source) return;

  pendingNaturalTextTranslations.set(node, source);
  void requestNaturalArabicTranslation(source).then((translated) => {
    if (activeDomLanguage !== 'ar') return;
    if (shouldSkipNode(node)) return;
    if (pendingNaturalTextTranslations.get(node) !== source) return;
    if ((originalText.get(node) ?? source) !== source) return;
    if (!translated || translated === source) return;

    const prefix = source.match(/^\s*/)?.[0] ?? '';
    const suffix = source.match(/\s*$/)?.[0] ?? '';
    const next = `${prefix}${translated.trim()}${suffix}`;
    node.nodeValue = next;
    renderedText.set(node, next);
  }).finally(() => {
    if (pendingNaturalTextTranslations.get(node) === source) {
      pendingNaturalTextTranslations.delete(node);
    }
  });
}

const ExperienceContext = createContext(null);

export function useUserExperience() {
  const value = useContext(ExperienceContext);
  if (!value) throw new Error('useUserExperience must be used inside UserExperienceProvider');
  return value;
}

export function UserExperienceProvider({ children }) {
  const [language, setLanguageState] = useState(() => {
    try { return localStorage.getItem(LANGUAGE_KEY) === 'ar' ? 'ar' : 'en'; } catch { return 'en'; }
  });
  const [theme, setThemeState] = useState(() => {
    try { return localStorage.getItem(THEME_KEY) === 'dark' ? 'dark' : 'light'; } catch { return 'light'; }
  });

  const setLanguage = useCallback((next) => {
    const safe = next === 'ar' ? 'ar' : 'en';
    setLanguageState(safe);
    try { localStorage.setItem(LANGUAGE_KEY, safe); } catch { /* ignore storage failures */ }
  }, []);

  const setTheme = useCallback((next) => {
    const safe = next === 'dark' ? 'dark' : 'light';
    setThemeState(safe);
    try { localStorage.setItem(THEME_KEY, safe); } catch { /* ignore storage failures */ }
  }, []);

  const value = useMemo(() => ({
    language,
    theme,
    isArabic: language === 'ar',
    isDark: theme === 'dark',
    setLanguage,
    setTheme,
    toggleLanguage: () => {
      const nextLanguage = language === 'ar' ? 'en' : 'ar';
      if (nextLanguage === 'ar') void getNaturalArabicTranslator();
      setLanguage(nextLanguage);
    },
    toggleTheme: () => setTheme(theme === 'dark' ? 'light' : 'dark'),
    t: (text) => (language === 'ar' ? translateToArabic(text) : text),
  }), [language, setLanguage, setTheme, theme]);

  return <ExperienceContext.Provider value={value}>{children}</ExperienceContext.Provider>;
}

const originalText = new WeakMap();
const renderedText = new WeakMap();
const originalAttributes = new WeakMap();
const renderedAttributes = new WeakMap();
const TRANSLATABLE_ATTRIBUTES = ['placeholder', 'title', 'aria-label', 'data-label', 'alt'];
let sourceDocumentTitle = null;
let renderedDocumentTitle = null;

function translatePageTitle(language) {
  const current = document.title ?? '';
  if (sourceDocumentTitle === null || (renderedDocumentTitle !== null && current !== renderedDocumentTitle)) {
    sourceDocumentTitle = current;
  }
  const source = sourceDocumentTitle ?? current;
  const next = language === 'ar' ? translateToArabic(source) : source;
  if (current !== next) document.title = next;
  renderedDocumentTitle = next;
}

function shouldSkipNode(node) {
  const parent = node.parentElement;
  if (!parent) return true;
  if (parent.closest('[data-no-auto-translate="true"]')) return true;
  if (parent.closest('[data-idea-content="true"]')) return true;
  if (parent.closest('[contenteditable="true"]')) return true;
  const tag = parent.tagName;
  return tag === 'SCRIPT' || tag === 'STYLE' || tag === 'CODE' || tag === 'PRE' || tag === 'TEXTAREA';
}

const ARABIC_PUBLICATION_REPORT_SELECTOR =
  '.admin-publication-reports-page, .admin-report-review-drawer, .admin-publication-reports-toast';

const DARK_ARABIC_AI_MODELS_SELECTOR =
  '.admin-model-page, .admin-model-modal, .admin-model-confirm';

function isDarkArabicAiModelsElement(element) {
  return Boolean(
    element &&
    document.documentElement.classList.contains('vox-user-dark') &&
    element.closest(DARK_ARABIC_AI_MODELS_SELECTOR),
  );
}

function translateAiModelsDarkArabic(value, element) {
  if (typeof value !== 'string') return value;
  const trimmed = value.trim();
  const prefix = value.match(/^\s*/)?.[0] ?? '';
  const suffix = value.match(/\s*$/)?.[0] ?? '';

  if (trimmed === 'AI model' && element?.closest('.admin-model-hero h1')) {
    return `${prefix}نماذج الذكاء الاصطناعي${suffix}`;
  }

  const exact =
    ADMIN_AI_MODELS_DARK_ARABIC_PHRASES[value] ||
    ADMIN_AI_MODELS_DARK_ARABIC_PHRASES[trimmed];
  if (exact) return value === trimmed ? exact : `${prefix}${exact}${suffix}`;

  const isolate = (text) => `\u2066${text}\u2069`;
  const patterns = [
    [/^(\d[\d,]*)\s+matching\s+models?$/i, (m) => `${m[1]} نموذج مطابق`],
    [/^(\d[\d,]*)\s+consecutive\s+failures?$/i, (m) => `${m[1]} حالة فشل متتالية`],
    [/^(\d[\d,.]*[KMB]?)\s+output(?:\s+·\s+(\d[\d,.]*[KMB]?)\s+context)?$/i, (m) => m[2] ? `${m[1]} إخراج · ${m[2]} سياق` : `${m[1]} إخراج`],
    [/^Showing\s+(\d+)[–-](\d+)\s+of\s+(\d+)$/i, (m) => `عرض ${m[1]}–${m[2]} من ${m[3]}`],
    [/^Page\s+(\d+)\s+of\s+(\d+)$/i, (m) => `الصفحة ${m[1]} من ${m[2]}`],
    [/^Last updated\s+(.+)$/i, (m) => `آخر تحديث ${translateAdminDateFragment(m[1])}`],
    [/^Manage\s+(.+)$/i, (m) => `إدارة ${isolate(m[1])}`],
    [/^Delete\s+(.+)\?$/i, (m) => `حذف ${isolate(m[1])}؟`],
    [/^(.+?)\s+is now the default model\.$/i, (m) => `تم تعيين ${isolate(m[1])} كنموذج افتراضي.`],
    [/^(.+?)\s+was removed from the model registry\.$/i, (m) => `تمت إزالة ${isolate(m[1])} من سجل النماذج.`],
  ];

  for (const [pattern, replacer] of patterns) {
    const match = trimmed.match(pattern);
    if (match) return `${prefix}${replacer(match)}${suffix}`;
  }

  return value;
}

function isArabicPublicationReportElement(element) {
  return Boolean(element && element.closest(ARABIC_PUBLICATION_REPORT_SELECTOR));
}

function translatePublicationReportArabic(value) {
  if (typeof value !== 'string') return value;
  const trimmed = value.trim();
  const exact =
    ADMIN_PUBLICATION_REPORT_DARK_ARABIC_PHRASES[value] ||
    ADMIN_PUBLICATION_REPORT_DARK_ARABIC_PHRASES[trimmed];

  const prefix = value.match(/^\s*/)?.[0] ?? '';
  const suffix = value.match(/\s*$/)?.[0] ?? '';
  if (exact) return value === trimmed ? exact : `${prefix}${exact}${suffix}`;

  const isolate = (text) => `\u2066${text}\u2069`;
  const patterns = [
    [/^(\d[\d,]*)\s+matching\s+reports?$/i, (m) => `${m[1]} بلاغات مطابقة`],
    [/^Page\s+(\d+)\s+of\s+(\d+)$/i, (m) => `الصفحة ${m[1]} من ${m[2]}`],
    [/^Reviewed\s+(.+)$/i, (m) => `تمت المراجعة ${translateAdminDateFragment(m[1])}`],
    [/^Published by\s+(.+)$/i, (m) => `نشر بواسطة ${isolate(m[1])}`],
    [/^(.+?)\s+·\s+submitted\s+(.+)$/i, (m) => {
      const translatedReason = translateToArabic(m[1]);
      return `${translatedReason} · أُرسل ${translateAdminDateFragment(m[2])}`;
    }],
    [/^Could not load idea\s+(details|insights)\.$/i, (m) =>
      m[1].toLowerCase() === 'details'
        ? 'تعذر تحميل تفاصيل الفكرة.'
        : 'تعذر تحميل إحصاءات الفكرة.'
    ],
  ];

  for (const [pattern, replacer] of patterns) {
    const match = trimmed.match(pattern);
    if (match) return `${prefix}${replacer(match)}${suffix}`;
  }

  if (trimmed.includes(' · ')) {
    const sourceParts = trimmed.split(' · ');
    const translatedParts = sourceParts.map((part) => {
      const special =
        ADMIN_PUBLICATION_REPORT_DARK_ARABIC_PHRASES[part] ||
        ADMIN_PUBLICATION_REPORT_DARK_ARABIC_PHRASES[part.trim()];
      return special || translateToArabic(part);
    });
    if (translatedParts.some((part, index) => part !== sourceParts[index])) {
      return `${prefix}${translatedParts.join(' · ')}${suffix}`;
    }
  }

  return translateToArabic(value);
}

function translateDom(language) {
  activeDomLanguage = language;
  translatePageTitle(language);
  const root = document.body;
  if (!root) return;

  const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT);
  const nodes = [];
  while (walker.nextNode()) nodes.push(walker.currentNode);

  for (const node of nodes) {
    if (shouldSkipNode(node)) continue;
    const current = node.nodeValue ?? '';
    const lastRendered = renderedText.get(node);

    if (!originalText.has(node)) {
      originalText.set(node, current);
    } else if (lastRendered !== undefined && current !== lastRendered) {
      // React updated this node after our previous translation. Keep the new
      // English/source value so counters, statuses and live content never go stale.
      originalText.set(node, current);
    }

    const source = originalText.get(node) ?? '';
    const useAiModelsDarkArabic =
      language === 'ar' && isDarkArabicAiModelsElement(node.parentElement);
    const usePublicationReportArabic =
      language === 'ar' && isArabicPublicationReportElement(node.parentElement);
    const next =
      language === 'ar'
        ? useAiModelsDarkArabic
          ? translateAiModelsDarkArabic(source, node.parentElement)
          : usePublicationReportArabic
            ? translatePublicationReportArabic(source)
            : translateToArabic(source)
        : source;
    if (current !== next) node.nodeValue = next;
    renderedText.set(node, next);

    if (language === 'ar' && next === source && !useAiModelsDarkArabic) {
      scheduleNaturalArabicTextTranslation(node, source);
    }
  }

  for (const element of root.querySelectorAll('*')) {
    if (element.closest('[data-no-auto-translate="true"], [data-idea-content="true"]')) continue;
    for (const attribute of TRANSLATABLE_ATTRIBUTES) {
      if (!element.hasAttribute(attribute)) continue;
      let store = originalAttributes.get(element);
      let renderedStore = renderedAttributes.get(element);
      if (!store) {
        store = {};
        originalAttributes.set(element, store);
      }
      if (!renderedStore) {
        renderedStore = {};
        renderedAttributes.set(element, renderedStore);
      }

      const current = element.getAttribute(attribute) ?? '';
      if (!(attribute in store)) {
        store[attribute] = current;
      } else if (attribute in renderedStore && current !== renderedStore[attribute]) {
        store[attribute] = current;
      }

      const source = store[attribute];
      const useAiModelsDarkArabic =
        language === 'ar' && isDarkArabicAiModelsElement(element);
      const usePublicationReportArabic =
        language === 'ar' && isArabicPublicationReportElement(element);
      const next =
        language === 'ar'
          ? useAiModelsDarkArabic
            ? translateAiModelsDarkArabic(source, element)
            : usePublicationReportArabic
              ? translatePublicationReportArabic(source)
              : translateToArabic(source)
          : source;
      if (current !== next) element.setAttribute(attribute, next);
      renderedStore[attribute] = next;
    }
  }
}

export function UserExperienceLayer() {
  const {
    language,
    theme,
    toggleLanguage,
    toggleTheme,
    isArabic,
    isDark,
    t,
  } = useUserExperience();

  useLayoutEffect(() => {
    const html = document.documentElement;

    html.classList.toggle('vox-user-dark', theme === 'dark');
    html.classList.toggle('vox-user-rtl', language === 'ar');
    html.setAttribute('data-vox-user-theme', theme);
    html.lang = language;
    html.dir = language === 'ar' ? 'rtl' : 'ltr';

    let translating = false;

    const apply = () => {
      if (translating) return;

      translating = true;

      try {
        translateDom(language);
      } finally {
        translating = false;
      }
    };

    apply();

    let frame = 0;

    const scheduleApply = () => {
      if (frame) return;

      frame = window.requestAnimationFrame(() => {
        frame = 0;
        apply();
      });
    };

    const observer = new MutationObserver(scheduleApply);
    const root = document.body;

    if (root) {
      observer.observe(root, {
        subtree: true,
        childList: true,
        characterData: true,
        attributes: true,
        attributeFilter: TRANSLATABLE_ATTRIBUTES,
      });
    }

    const sweep =
      language === 'ar'
        ? window.setInterval(scheduleApply, 700)
        : 0;

    window.addEventListener('focus', scheduleApply);

    return () => {
      observer.disconnect();

      if (frame) {
        window.cancelAnimationFrame(frame);
      }

      if (sweep) {
        window.clearInterval(sweep);
      }

      window.removeEventListener('focus', scheduleApply);
    };
  }, [language, theme]);

  return (
    <div
      className="vox-experience-controls"
      data-no-auto-translate="true"
      dir="ltr"
    >
      <button
        type="button"
        className="vox-experience-button vox-experience-button--language"
        onClick={toggleLanguage}
        aria-label={
          isArabic
            ? 'Switch to English'
            : 'التبديل إلى العربية'
        }
        title={
          isArabic
            ? 'Switch to English'
            : 'التبديل إلى العربية'
        }
      >
        <Languages size={16} aria-hidden="true" />
        <span>{isArabic ? 'EN' : 'AR'}</span>
      </button>

      <button
        type="button"
        className="vox-experience-button"
        onClick={toggleTheme}
        aria-label={
          isDark
            ? t('Light mode')
            : t('Dark mode')
        }
        title={
          isDark
            ? t('Light mode')
            : t('Dark mode')
        }
      >
        {isDark ? (
          <Sun size={17} aria-hidden="true" />
        ) : (
          <Moon size={17} aria-hidden="true" />
        )}
      </button>
    </div>
  );
}
